function ContactForm(){const[status,setStatus]=useState('idle'),[message,setMessage]=useState('');const submit=async e=>{e.preventDefault();const f=e.currentTarget;if(!f.reportValidity())return;setStatus('sending');setMessage('');try{const r=await fetch('/api/inquiry',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(f)))}),x=await r.json().catch(()=>({}));if(!r.ok)throw new Error(x.error||'Unable to send your request right now.');setStatus('sent');f.reset()}catch(err){setStatus('error');setMessage(err.message)}};if(status==='sent')return html`<div className="estimate-form form-success"><span><${Icon} name="check" size=${28}/></span><h3>Thanks for reaching out.</h3><p>Your inquiry was sent to RESA Construction. We’ll be in touch soon.</p><button className="text-link" type="button" onClick=${()=>setStatus('idle')}>Submit another request</button></div>`;return html`<form className="estimate-form reveal in" onSubmit=${submit}><div className="form-row"><label>Full Name<input name="name" required minLength="2" placeholder="Your name"/></label><label>Phone Number<input name="phone" required type="tel" minLength="7" placeholder="(000) 000-0000"/></label></div><div className="form-row"><label>Email Address<input name="email" required type="email" placeholder="you@email.com"/></label><label>Project Location<input name="location" required minLength="3" placeholder="Street, City"/></label></div><label>Service Needed<select name="service" required defaultValue=""><option value="" disabled>Select a service</option>${['Residential Construction','Addition','New Construction','Kitchen Remodeling','Bathroom Remodeling','Panel Upgrade','Lighting Installation','Rewiring','EV Charger Installation','Other'].map(x=>html`<option>${x}</option>`)}</select></label><label>Project Description<textarea name="description" required minLength="10" rows="4" placeholder="Tell us about your project, timeline, and any important details."></textarea></label><fieldset><legend>Preferred Method of Contact</legend><label className="radio"><input type="radio" name="contactMethod" value="Phone call" defaultChecked/> Phone call</label><label className="radio"><input type="radio" name="contactMethod" value="Email"/> Email</label></fieldset>${status==='error'&&html`<p className="form-error" role="alert">${message}</p>`}<button className="btn orange submit" disabled=${status==='sending'} type="submit">${status==='sending'?'Sending…':'Submit Request'} <${Icon} name="arrow"/></button></form>`}
export function App(){const[open,setOpen]=useState(false);useEffect(()=>{const els=document.querySelectorAll('.reveal'),o=new IntersectionObserver(es=>es.forEach(e=>e.isIntersecting&&e.target.classList.add('in')),{threshold:.12});els.forEach(e=>o.observe(e));return()=>o.disconnect()},[]);const go=id=>{setOpen(false);document.getElementById(id)?.scrollIntoView({behavior:'smooth'})};return html`<header className="site-header"><a href="#home" className="brand" onClick=${e=>{e.preventDefault();go('home')}}><span className="brand-mark">R</span><span>RESA <b>Construction</b><small>Residential + Electrical</small></span></a><nav className=${open?'main-nav open':'main-nav'}>${nav.map(([l,id])=>html`<a href=${'#'+id} onClick=${e=>{e.preventDefault();go(id)}}>${l}</a>`)}</nav><button className="header-cta" onClick=${()=>go('contact')}>Get a Free Estimate <${Icon} name="arrow" size=${17}/></button><button className="menu-toggle" aria-label="Toggle menu" onClick=${()=>setOpen(!open)}><${Icon} name=${open?'close':'menu'}/></button></header><main><section className="hero" id="home"><div className="hero-image"></div><div className="hero-shade"></div><div className="hero-content"><p className="eyebrow light">SOUTH BAY AREA · RESIDENTIAL CONSTRUCTION & ELECTRICAL</p><h1>Quality Construction.<br/><em>Reliable Electrical Work.</em></h1><p className="hero-copy">Residential construction and electrical services backed by years of experience, professional workmanship, and dependable service.</p><div className="hero-actions"><button className="btn orange" onClick=${()=>go('contact')}>Get a Free Estimate <${Icon} name="arrow"/></button><a className="btn ghost" href=${PHONE_LINK}><${Icon} name="phone"/> ${PHONE}</a></div></div><div className="hero-foot"><span>Serving homeowners since 2012</span><span>License #974362</span><span>Insured & Bonded</span></div></section><section className="intro section" id="about"><div className="intro-kicker reveal"><span className="orange-line"></span><p className="eyebrow">ESTABLISHED 2012</p><h2>Built on care.<br/>Backed by craft.</h2></div><div className="intro-copy reveal"><p className="lead">RESA Construction is a dependable partner for South Bay homeowners who value clear communication, lasting work, and a job done right.</p><p>From small electrical installations to full remodeling, additions, and new construction, our team brings disciplined planning and attention to detail to every project. We prioritize safety, respect your home, and stand behind the quality of our workmanship.</p><button className="text-link" onClick=${()=>go('contact')}>Talk with our team <${Icon} name="arrow" size=${18}/></button></div><div className="stats reveal"><div><b>14+</b><span>Years serving homeowners</span></div><div><b>100%</b><span>Committed to quality work</span></div><div><b>1</b><span>Trusted team for build + electrical</span></div></div></section><section className="services section" id="services"><div className="section-head reveal"><div><p className="eyebrow">WHAT WE DO</p><h2>One trusted team for<br/><em>your whole home.</em></h2></div><p>Construction and electrical expertise, coordinated from the first plan to the final detail.</p></div><div className="service-grid">${services.map(([t,x,i],n)=>html`<article className="service-card reveal" style=${{transitionDelay:`${n*35}ms`}}><div className="service-icon"><${Icon} name=${i}/></div><h3>${t}</h3><p>${x}</p><button aria-label=${'Learn more about '+t} onClick=${()=>go('contact')}><${Icon} name="arrow" size=${19}/></button></article>`)}</div><aside className="ev-promo reveal"><div><p className="eyebrow light">SPECIALIZED HOME ELECTRICAL</p><h3>EV Charger Installation</h3><p>Professional electric vehicle charger installation for residential properties.</p></div><button className="btn orange" onClick=${()=>go('contact')}>Request an estimate <${Icon} name="arrow"/></button></aside></section><section className="why section" id="why"><div className="why-photo reveal"><div className="license-badge"><${Icon} name="shield" size=${25}/><span>Licensed<br/><b>#974362</b></span></div></div><div className="why-content reveal"><p className="eyebrow">WHY RESA</p><h2>Experience you can<br/><em>feel confident in.</em></h2><p className="lead-sm">A straightforward, safety-focused approach that keeps projects moving and homeowners informed.</p><div className="check-list">${['In Business Since 2012','Licensed Contractor — #974362','Insured & Bonded','Construction & Electrical Expertise','Quality Workmanship','Reliable Service','Safety-Focused','Free Estimates'].map(x=>html`<div><span><${Icon} name="check" size=${16}/></span>${x}</div>`)}</div></div></section><section className=${projects.length ? "projects section" : "projects section projects-empty"} id="projects"><div className="section-head reveal"><div><p className="eyebrow">OUR PROJECTS</p><h2>Project Gallery</h2></div></div><div className="project-grid" id="project-gallery">${projects.map((project,n)=>html`<figure className="portfolio-card reveal"><a href=${project.src} target="_blank" rel="noopener noreferrer" aria-label=${`View project photo: ${project.alt}`}><div className="portfolio-media"><img src=${project.src} alt=${project.alt} loading=${n<2?"eager":"lazy"}/><span className="portfolio-action">View Project <${Icon} name="arrow" size=${16}/></span></div></a><figcaption>${project.label}</figcaption></figure>`)}</div></section><section className="cta"><div className="cta-inner"><p className="eyebrow light">SOUTH BAY AREA · LET'S BUILD SOMETHING GOOD</p><h2>Planning a construction<br/>or electrical project?</h2><p>Call <a href=${PHONE_LINK}>${PHONE}</a> or contact RESA Construction today to discuss your project and request an estimate.</p><button className="btn orange" onClick=${()=>go('contact')}>Request a Free Estimate <${Icon} name="arrow"/></button></div></section><section className="contact section" id="contact"><div className="contact-info reveal"><p className="eyebrow">GET IN TOUCH</p><h2>Tell us about<br/><em>your project.</em></h2><p>Share a few details and our team will be in touch to discuss the next steps.</p><div className="contact-details"><div><span><${Icon} name="phone"/></span><p><b>Phone</b><a href=${PHONE_LINK}>${PHONE}</a></p></div><div><span><${Icon} name="mail"/></span><p><b>Email</b><a href=${'mailto:'+EMAIL}>${EMAIL}</a></p></div><div><span><${Icon} name="map"/></span><p><b>Service Area</b><i>South Bay Area</i></p></div><div><span><${Icon} name="clock"/></span><p><b>Business Hours</b><i>8:00 AM - 6:00 PM</i></p></div></div></div><${ContactForm}/></section></main><footer><div className="footer-brand"><a className="brand" href="#home" onClick=${e=>{e.preventDefault();go('home')}}><span className="brand-mark">R</span><span>RESA <b>Construction</b><small>Residential + Electrical</small></span></a><p>Serving South Bay homeowners with professional construction and electrical services since 2012.</p><a href=${PHONE_LINK}>${PHONE}</a><a href=${'mailto:'+EMAIL}>${EMAIL}</a><span>South Bay Area · 8:00 AM - 6:00 PM<br/>License #974362 &nbsp;•&nbsp; Insured & Bonded</span></div><div className="footer-links">${nav.map(([l,id])=>html`<a href=${'#'+id} onClick=${e=>{e.preventDefault();go(id)}}>${l}</a>`)}</div><p className="copyright">© 2026 RESA Construction. All Rights Reserved.</p></footer><div className="mobile-actions"><a href=${PHONE_LINK}><${Icon} name="phone"/> Call ${PHONE}</a><button onClick=${()=>go('contact')}><${Icon} name="arrow"/> Get Estimate</button></div>`}
